extraHTML.extraHead:
  // Put this as the very first line of Extra HTML content:
<meta name="robots" content="noindex" />
    <script type="application/ld+json">
      {
        "@context": "https://schema.org",
        "@type": "FAQPage",
        "mainEntity": [
          {
            "@type": "Question",
            "name": "Is Bartesian discontinued?",
            "acceptedAnswer": {
              "@type": "Answer",
              "text": "<p>No. Bartesian is not discontinued and will not be discontinued. Bartesian creates new cocktail offerings monthly and recently released a new cocktail maker, the Bartesian Duet, to bring even more options to this fast-growing market.</p>"
            }
          },
          {
            "@type": "Question",
            "name": "About Bartesian",
            "acceptedAnswer": {
              "@type": "Answer",
              "text": "<p>Bartesian is an innovative, effortless way to enjoy and serve premium cocktails on-demand at the press of a button. Bartesian was made to not only be perfect at home but for Food Service/Hospitality applications as well.</p>"
            }
          },
          {
            "@type": "Question",
            "name": "Contact Bartesian",
            "acceptedAnswer": {
              "@type": "Answer",
              "text": "<p>For Bartesian appliance hardware/operational inquiries, our hardware care team is available via support@bartesian.com. For all general/sales, and order inquiries, our sales team is available to assist via hello@bartesian.com.</p>"
            }
          },
          {
            "@type": "Question",
            "name": "Does Bartesian ship internationally?",
            "acceptedAnswer": {
              "@type": "Answer",
              "text": "<p>Currently, orders placed on Bartesian.com are exclusively shipped within North America (excluding Quebec). Stay tuned to our Newsletter for updates and developments on International availability.</p>"
            }
          },
          {
            "@type": "Question",
            "name": "Is there alcohol in the capsules?",
            "acceptedAnswer": {
              "@type": "Answer",
              "text": "<p>Bartesian capsules do not contain alcohol. This gives you the freedom not only to use the spirits of your own choosing but Bartesian also allows you to customize your cocktail from mocktail to strong.</p>"
            }
          }
        ]
      }
    </script>
